    # simpler: find vertical run of length>=2 where two distinct colors each appear few times, third = one of them repeated
    for c in range(C):
        for r in range(R-1):
            a,b=I[r][c],I[r+1][c]
            if a!=b and cnt[a]<=3 and cnt[b]<=3:
