                d[(nr,nc)]=d[(r,c)]+1; dq.append((nr,nc))
    out=I.copy()
    for (r,c),v in d.items():
        out[r][c]= rar if v%2==0 else mid
    return [[int(x) for x in row] for row in out]
for k in [1,2,3,4,5]:
    o=solve(G[f'Demo pair {k} input']); e=G[f'Demo pair {k} output']
    print(k,'match:',o==e, '' if o==e else [(r,c,o[r][c],e[r][c]) for r in range(len(o)) for c in range(len(o[0])) if o[r][c]!=e[r][c]][:6])
